 }

+security_nvidia_acceleration_enabled() {
+  nvidia_addon_selected=${NVIDIA_ADDON_SELECTED:-false}
+  nvidia_gpu_detected=${NVIDIA_GPU_DETECTED:-false}
+
+  case "$nvidia_addon_selected" in
+    true|false) ;;
