    if shutil.which(executable) is None and not os.path.exists(executable):
        fail(f"application executable is missing: {executable}")

    validate_required_runtime_files(options.application)
    if options.mode != "pure-privacy":
        home_dir = os.environ.get("HOME", str(pathlib.Path.home()))
        ensure_managed_runtime_state(
            options.application,
            home_dir,
        )
        if options.application == "obsidian":
            ensure_obsidian_registry(home_dir)
    if options.mode == "pure-privacy":
        return run_pure_privacy(options.application, options.args)
    if app.get("persistent_sandbox", False):
        return run_persistent_sandbox(options.application, options.mode, options.args)

    env = build_environment(options.application, options.mode)
    argv = build_argv(options.application, options.mode, options.args)
    os.execvpe(argv[0], argv, env)
